/**
 * Guardian Portal Data (Supabase-backed)
 * Replaces mock data with real database queries.
 */
export {
  getStudentsByGuardian,
  getStudentAttendance,
  getStudentAttendanceStats,
  getStudentResults,
  getStudentChallans,
  getAnnouncementsByRole,
  getAllAnnouncements,
} from './db';

import { supabase } from './supabaseClient';

/**
 * Get full guardian portal data for a specific child
 * Assembles schedule, attendance, results from Supabase
 */
export async function getChildData(studentId) {
  // Get student with class info
  const { data: student } = await supabase
    .from('students')
    .select(`
      *,
      class:session_classes(
        id, class_name, section, semester,
        course:session_courses(course_name, course_code)
      ),
      guardian:guardians(
        id,
        user:users(first_name, last_name, cnic, phone)
      )
    `)
    .eq('id', studentId)
    .single();

  if (!student) return null;

  // Get class subjects (schedule)
  const { data: subjects } = await supabase
    .from('class_subjects')
    .select(`
      *,
      teacher:teachers(
        user:users(first_name, last_name)
      )
    `)
    .eq('class_id', student.class?.id);

  // Get attendance records
  const { data: attendanceRecords } = await supabase
    .from('attendance_records')
    .select(`
      *,
      subject:class_subjects(subject_name, subject_code)
    `)
    .eq('student_id', studentId)
    .order('date', { ascending: false });

  // Compute attendance stats
  const total = attendanceRecords?.length || 0;
  const present = attendanceRecords?.filter(r => r.status === 'present').length || 0;
  const absent = attendanceRecords?.filter(r => r.status === 'absent').length || 0;
  const leave = attendanceRecords?.filter(r => r.status === 'leave').length || 0;

  // Get results
  const { data: results } = await supabase
    .from('results')
    .select(`
      *,
      subject:class_subjects(subject_name, subject_code)
    `)
    .eq('student_id', studentId);

  return {
    ...student,
    studentName: `${student.first_name} ${student.last_name}`,
    rollNo: student.roll_no,
    classSection: student.class ? `${student.class.course?.course_code} - ${student.class.semester} Semester (Sec ${student.class.section})` : '',
    guardianName: student.guardian?.user ? `${student.guardian.user.first_name} ${student.guardian.user.last_name}` : '',
    guardianCnic: student.guardian?.user?.cnic || '',
    guardianPhone: student.guardian?.user?.phone || '',
    overallAttendance: total > 0 ? `${((present / total) * 100).toFixed(1)}%` : 'N/A',
    studyProgress: total > 0 ? Math.round((present / total) * 100) : 0,
    schedule: (subjects || []).map((s, i) => ({
      id: i + 1,
      course: s.subject_name,
      code: s.subject_code,
      creditHours: s.credit_hours,
      teacher: s.teacher?.user ? `${s.teacher.user.first_name} ${s.teacher.user.last_name}` : 'TBA',
    })),
    attendance: {
      stats: { totalClasses: total, present, absent, leave, percentage: total > 0 ? parseFloat(((present / total) * 100).toFixed(1)) : 0 },
      records: (attendanceRecords || []).map((r, i) => ({
        id: i + 1,
        date: r.date,
        subject: r.subject?.subject_name || '',
        status: r.status.charAt(0).toUpperCase() + r.status.slice(1),
      })),
    },
    results: (results || []).map((r, i) => ({
      id: i + 1,
      subject: r.subject?.subject_name || '',
      code: r.subject?.subject_code || '',
      examType: r.exam_type,
      marksObtained: r.marks_obtained,
      totalMarks: r.total_marks,
      grade: r.grade,
    })),
  };
}
